```python
def transform(grid):
    if not grid or not grid[0]:
        return grid

    R, C = len(grid), len(grid[0])
    from collections import defaultdict

    # Find background (most frequent value)
    counts = defaultdict(int)
    for row in grid:
        for val in row:
            counts[val] += 1
    bg = max(counts, key=counts.get)

    # Collect non-background positions by color
    by_color = defaultdict(list)
    for r in range(R):
        for c in range(C):
            if grid[r][c] != bg:
                by_color[grid[r][c]].append((r, c))

    out = [list(row) for row in grid]

    for color, pos_list in by_color.items():
        if len(pos_list) < 2:
            continue

        pos_list = sorted(pos_list, key=lambda x: (x[0], x[1]))

        # Find consecutive diagonal pairs
        pairs = []
        for i in range(len(pos_list) - 1):
            r0, c0 = pos_list[i]
            r1, c1 = pos_list[i + 1]
            if abs(r1 - r0) == 1 and abs(c1 - c0) == 1:
                dr = r1 - r0
                dc = c1 - c0
                pairs.append((dr, dc, r1, c1))

        if not pairs:
            continue

        # Use direction from the last consecutive pair for extension
        dr, dc, last_r, last_c = pairs[-1]

        # Extend from the end position in the diagonal direction
        r, c = last_r, last_c
        while True:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C:
                if out[nr][nc] == bg:
                    out[nr][nc] = color
                else:
                    break
            else:
                break

    return out
